// Post-processes `drizzle-kit pull` output (lib/db/generated/schema.ts):
//  - citext columns: drizzle-kit emits `unknown("col")` → map to a citext customType
//  - timestamps: use mode 'date' (Better Auth and app code work with Date objects)
// Run via `pnpm db:pull`. Never hand-edit the generated file.
import { readFileSync, readdirSync, rmSync, writeFileSync } from 'node:fs';

const file = new URL('../lib/db/generated/schema.ts', import.meta.url);
let s = readFileSync(file, 'utf8');
s = s.replace(/\s*\/\/ TODO: failed to parse database type 'citext'\n/g, '\n');
s = s.replace(/unknown\("([a-z_]+)"\)/g, 'citext("$1")');
s = s.replace(/mode: 'string'/g, "mode: 'date'");
// drizzle-kit renders an empty-string default as `.default(')` — repair it
s = s.replace(/\.default\('\)/g, ".default('')");
if (!s.includes('customType')) {
  s = s.replace(
    /^import \{ ([^}]+) \} from "drizzle-orm\/pg-core"/m,
    (_m, names) => `import { ${names}, customType } from "drizzle-orm/pg-core"`,
  );
  s = s.replace(
    /^(import \{ sql \} from "drizzle-orm"\n)/m,
    `$1\nconst citext = customType<{ data: string }>({ dataType: () => 'citext' });\n`,
  );
}
// Self-referencing FKs (e.g. articles ↔ article_versions) make tsc report implicit-any cycles in generated code.
if (!s.startsWith('// @ts-nocheck')) s = '// @ts-nocheck — generated by drizzle-kit pull + scripts/fix-drizzle-schema.mjs\n' + s;
writeFileSync(file, s);
// drizzle-kit also writes a snapshot migration; SQL files in db/migrations are the only migrations
for (const f of readdirSync(new URL('../lib/db/generated/', import.meta.url)).filter((n) => n.endsWith('.sql'))) {
  rmSync(new URL(`../lib/db/generated/${f}`, import.meta.url));
}
for (const extra of ['meta']) rmSync(new URL(`../lib/db/generated/${extra}`, import.meta.url), { recursive: true, force: true });
console.log('schema.ts fixed');
